async function v2UpdateFriendDiscussion(sessionId, message, change) {
  // Every database update advances updated_at. Re-read before merging when another participant wins the write.
  for (let attempt = 0; attempt < 6; attempt++) {
    const {data: row, error: readError} = await $.from("debate_sessions")
      .select("updated_at,current_phase,shared_data,user_a,user_b").eq("id",sessionId).single();
    if (readError || !row?.updated_at) throw readError || new Error("The discussion could not be loaded.");
    const shared = row.shared_data || {};
    const messages = shared.chat_messages || [];
    if (message && messages.some(saved => saved.id === message.id)) return row;
    const patch = change(row, shared, message ? [...messages, message] : messages);
    if (!patch) return row;
    const {data: saved, error: writeError} = await $.from("debate_sessions").update(patch)
      .eq("id",sessionId).eq("updated_at",row.updated_at).select("id").maybeSingle();
    if (writeError) throw writeError;
    if (saved) return {...row,...patch};
  }
  throw new Error("Your partner also updated the discussion. Please try again.");
}
