function v2UpdateTopicProposal(sessionId, action, proposal, message, actor) {
  return v2UpdateFriendDiscussion(sessionId, message, (row, shared, messages) => {
    if (!["matching","topic_selection"].includes(row.current_phase)) throw new Error("The discussion has moved to the next step.");
    const current = shared.topic_proposal;
    const updated = {...shared, chat_messages: messages};
    if (action === "propose") {
      if (current) throw new Error("Your partner proposed a topic. Review the current proposal.");
      updated.topic_proposal = proposal;
    } else {
      if (!current || current.topic !== proposal.topic || current.proposed_at !== proposal.proposed_at ||
          current.proposed_by !== proposal.proposed_by) throw new Error("The topic changed. Review the current proposal.");
      if (action === "decline") {
        delete updated.topic_proposal;
      } else {
        const agreed = [...new Set([...(current.agreed_by || []), actor])];
        updated.topic_proposal = {...current, agreed_by: agreed};
